const countDistinctTypes = (cards: Card[]): number =>
  new Set(cards.map((card) => card.monster)).size;

const BASE_SCORE = 1;
const MINIMUM_BONUS = 1;
const POINTS_PER_EXTRA_TYPE = 2;
const TYPES_BEFORE_BONUS = 3;

// Every Sphinx in an army scores the same: the score depends only on how
// varied the rest of the army is, not on which Sphinx card we are looking at.
const scorePerSphinx = (army: Card[]): number => {
  const otherTypes = countDistinctTypes(army.filter((card) => !isSphinx(card)));
  const extraTypes = otherTypes - TYPES_BEFORE_BONUS;
  const bonus =
    extraTypes > 0 ? POINTS_PER_EXTRA_TYPE * extraTypes : MINIMUM_BONUS;
  return BASE_SCORE + bonus;
};

const countSphinxes = (army: Card[]): number => army.filter(isSphinx).length;

export const scoreArmy = (army: Card[]): number =>
  countSphinxes(army) * scorePerSphinx(army);
